import {
  ResourceGroupFairShareStepQuery,
  ResourceGroupOrderBy,
} from '../../__generated__/ResourceGroupFairShareStepQuery.graphql';
import { convertToOrderBy } from '../../helper';
import { useSuspendedBackendaiClient } from '../../hooks';
import { useBAIPaginationOptionStateOnSearchParam } from '../../hooks/reactPaginationQueryOptions';
import FairShareStepToolbar, {
  flattenUnsupportedSubFilter,
} from './FairShareStepToolbar';
import ResourceGroupFairShareTable, {
  availableResourceGroupSorterValues,
  resourceGroupOrderFieldMap,
} from './ResourceGroupFairShareTable';
import { BAIFlex, INITIAL_FETCH_KEY, useFetchKey } from 'backend.ai-ui';
import * as _ from 'lodash-es';
import { parseAsJson, parseAsStringLiteral, useQueryStates } from 'nuqs';
import { useDeferredValue } from 'react';
import { useTranslation } from 'react-i18next';
import { graphql, useLazyLoadQuery } from 'react-relay';

interface ResourceGroupFairShareStepProps {
  loading?: boolean;
  onClickResourceGroupName?: (resourceGroupName: string) => void;
}

const ResourceGroupFairShareStep: React.FC<ResourceGroupFairShareStepProps> = ({
  loading,
  onClickResourceGroupName,
}) => {
  'use memo';

  const { t } = useTranslation();

  // Two conditions serialize as `{ AND: [...] }`, which needs `sub-filter`
  // (26.7+); this step is reachable from 26.2. Below 26.7 expose only the
  // property that shipped before FR-3920, capped at one condition.
  // TODO(FR-3920): once #9638's `maxConditions` lands, show them with
  // `maxConditions={1}` instead of hiding them.
  const supportsSubFilter =
    useSuspendedBackendaiClient().supports('sub-filter');

  const {
    baiPaginationOption,
    tablePaginationOption,
    setTablePaginationOption,
  } = useBAIPaginationOptionStateOnSearchParam({
    current: 1,
    pageSize: 10,
  });

  const [queryParams, setQueryParams] = useQueryStates(
    {
      order: parseAsStringLiteral(availableResourceGroupSorterValues),
      filter: parseAsJson<any>((value) => value),
    },
    {
      history: 'replace',
    },
  );

  // A URL written before this gate (or on a newer manager) can still carry
  // an AND/OR/NOT combinator the filter control can no longer produce here.
  const effectiveFilter = supportsSubFilter
    ? queryParams.filter
    : flattenUnsupportedSubFilter(queryParams.filter);

  const queryVariables = {
    filter: {
      ...(effectiveFilter || {}),
    },
    order: convertToOrderBy<ResourceGroupOrderBy>(
      queryParams.order,
      resourceGroupOrderFieldMap,
    ) || [{ field: 'NAME', direction: 'ASC' }],
    limit: baiPaginationOption.limit,
    offset: baiPaginationOption.offset,
  };
  const deferredQueryVariables = useDeferredValue(queryVariables);
  const [fetchKey, updateFetchKey] = useFetchKey();
  const deferredFetchKey = useDeferredValue(fetchKey);

  const { resourceGroups } = useLazyLoadQuery<ResourceGroupFairShareStepQuery>(
    graphql`
      query ResourceGroupFairShareStepQuery(
        $filter: ResourceGroupFilter
        $order: [ResourceGroupOrderBy!]
        $limit: Int
        $offset: Int
      ) {
        resourceGroups: adminResourceGroups(
          filter: $filter
          orderBy: $order
          limit: $limit
          offset: $offset
        ) {
          count
          edges {
            node {
              ...ResourceGroupFairShareTableFragment
            }
          }
        }
      }
    `,
    deferredQueryVariables,
    {
      fetchKey: deferredFetchKey,
      fetchPolicy:
        deferredFetchKey === INITIAL_FETCH_KEY
          ? 'store-and-network'
          : 'network-only',
    },
  );

  return (
    <BAIFlex direction="column" align="stretch" gap="xs">
      <FairShareStepToolbar
        singleCondition={!supportsSubFilter}
        filterProperties={[
          {
            key: 'name',
            propertyLabel: t('fairShare.Name'),
            type: 'string',
          },
          ...(supportsSubFilter
            ? ([
                {
                  key: 'description',
                  propertyLabel: t('resourceGroup.Description'),
                  type: 'string',
                },
                {
                  key: 'isActive',
                  propertyLabel: t('resourceGroup.ActiveStatus'),
                  type: 'boolean',
                },
                {
                  key: 'isPublic',
                  propertyLabel: t('resourceGroup.PublicStatus'),
                  type: 'boolean',
                },
              ] as const)
            : []),
        ]}
        filterValue={effectiveFilter || {}}
        onChangeFilter={(filter) => {
          setQueryParams({
            filter: filter || null,
          });
          setTablePaginationOption({ current: 1 });
        }}
        fetchKeyLoading={fetchKey !== deferredFetchKey}
        onRefresh={() => {
          updateFetchKey();
        }}
      />
      <ResourceGroupFairShareTable
        resourceGroupNodeFragment={
          resourceGroups?.edges?.map((edge) => edge?.node) || null
        }
        onClickGroupName={(name) => {
          onClickResourceGroupName?.(name);
        }}
        loading={
          loading ||
          queryVariables !== deferredQueryVariables ||
          fetchKey !== deferredFetchKey
        }
        pagination={{
          pageSize: tablePaginationOption.pageSize,
          total: resourceGroups?.count || 0,
          current: tablePaginationOption.current,
          onChange: (current, pageSize) => {
            if (_.isNumber(current) && _.isNumber(pageSize)) {
              setTablePaginationOption({
                current,
                pageSize,
              });
            }
          },
        }}
      />
    </BAIFlex>
  );
};

export default ResourceGroupFairShareStep;
